-- 外研社七下 wy7B 阅读合并灌库(junior_reading)· publisher=junior_fltrp · volume=wy7B · grade=7
-- 30篇 = 6精读(difficulty=0·5题)+ 24泛读(difficulty=1·3题·每单元4篇)。原文全改写/原创,无版权原文入库。
-- 幂等:按(publisher,volume)先删后插。id 不预生成(DB默认)。★合并版:精读+泛读同一DELETE,勿再单独跑旧精读版★
BEGIN;

DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B';

-- U1 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'The kite my grandpa made', 'When I was seven, my family did not have much money. On my birthday, I hoped for a new toy, but my grandpa gave me an old paper kite. He made it himself with bamboo and some old newspaper. At first I felt a little sad, because my friends had bright new toys. That afternoon, Grandpa took me to a green hill near our home. The wind was strong, and the kite flew high into the blue sky. Grandpa held my hand and we ran together, laughing. The kite looked like a little bird above us. Other children stopped to watch us, and some of them wanted to try, too. We stayed on the green hill until the sun went down. "Money can buy toys," Grandpa said, "but it cannot buy this happy time." I looked at his kind smile and suddenly I understood. That old kite was a wonderful gift. Years later, I still remember that day. Happiness was not in the shops; it was in my grandpa''s warm hands.', '幸福的秘密·一份简单的礼物', 175, 0, '[{"q": "What did Grandpa give the writer for the birthday?", "answer": "B", "options": ["A new toy from the shop.", "An old paper kite he made.", "A big blue bird.", "Some money."], "explanation": "原文\"my grandpa gave me an old paper kite. He made it himself\"。"}, {"q": "Where did Grandpa take the writer to fly the kite?", "answer": "A", "options": ["A green hill near their home.", "A busy shop in town.", "A river far away.", "The school playground."], "explanation": "原文\"took me to a green hill near our home\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["New toys make children happy.", "Grandpa was very poor.", "Real happiness does not come from money.", "Kites are easy to make."], "explanation": "祖父的话与结尾点题:幸福不来自金钱。"}, {"q": "Why did the writer feel sad at first?", "answer": "D", "options": ["The kite was broken.", "The wind was too strong.", "Grandpa was angry.", "The writer wanted a new toy like the friends had."], "explanation": "\"my friends had bright new toys\",作者也想要新玩具,靠推断。"}, {"q": "In the passage, \"happiness\" means ____.", "answer": "A", "options": ["a warm and joyful feeling", "a kind of new toy", "a strong wind", "a lot of money"], "explanation": "由全文可推断 happiness=幸福、快乐的感觉。"}]'::jsonb, '[{"word": "bamboo", "cn": "竹子"}, {"word": "suddenly", "cn": "突然"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'A day at the zoo', 'Last Sunday, my family went to the zoo. It was a warm and sunny day. First, we saw the pandas. They sat quietly and ate bamboo all morning. Then we watched the monkeys. They jumped from tree to tree and made us laugh. At noon, we had lunch near the lake. My little brother fed the ducks with some bread. In the afternoon, we saw the lions and the big elephants. I took many photos of them. Before we left, I bought a small toy tiger. I was tired but very happy. On the way home, my brother fell asleep in the car. It was a wonderful day in my holiday.', '动物园的一天(一般过去时)', 111, 1, '[{"q": "What did the pandas do all morning?", "answer": "B", "options": ["Jumped from tree to tree.", "Sat quietly and ate bamboo.", "Swam in the lake.", "Slept in a cage."], "explanation": "''They sat quietly and ate bamboo all morning''。"}, {"q": "What did the writer buy before leaving?", "answer": "A", "options": ["A small toy tiger.", "A photo.", "Some bread.", "A book."], "explanation": "''I bought a small toy tiger''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to feed ducks.", "Why pandas eat bamboo.", "A happy day the writer spent at the zoo.", "Where the zoo is."], "explanation": "全文讲在动物园度过的快乐一天(过去时)。"}]'::jsonb, '[{"word": "zoo", "cn": "动物园"}, {"word": "bamboo", "cn": "竹子"}, {"word": "fed", "cn": "喂(feed的过去式)"}, {"word": "elephants", "cn": "大象"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'My best birthday', 'Last week was my twelfth birthday, and it was wonderful. In the morning, my mother made a big chocolate cake. My friends came to my house in the afternoon. They brought me many nice presents and colourful cards. We played games in the garden and sang songs together. At six o''clock, we sat around the table. I made a wish and blew out the candles. Everyone laughed and cheered. After dinner, we watched a funny film. My best friend gave me a book about faraway places. We ate cake and told jokes until it was dark. I did not want the day to end. It was a wonderful birthday, and I will always remember it.', '最棒的生日(一般过去时)', 116, 1, '[{"q": "What did the writer''s mother make in the morning?", "answer": "D", "options": ["A card.", "A toy.", "A song.", "A big chocolate cake."], "explanation": "''my mother made a big chocolate cake''。"}, {"q": "What did the best friend give the writer?", "answer": "C", "options": ["A cake.", "A card.", "A book about faraway places.", "A film."], "explanation": "''My best friend gave me a book about faraway places''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to make a cake.", "Why friends are late.", "Where the garden is.", "The writer''s wonderful birthday."], "explanation": "全文讲最快乐的生日(过去时)。"}]'::jsonb, '[{"word": "presents", "cn": "礼物"}, {"word": "cards", "cn": "贺卡"}, {"word": "wish", "cn": "愿望"}, {"word": "blew", "cn": "吹(blow的过去式)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'The lost key', 'Did you ever lose something important? Yesterday, something worried me a lot. When I got home from school, I could not find my key. I looked in my school bag, but it was not there. I looked in every pocket of my coat. I even looked under the desk and behind the door. My heart beat fast. Then I remembered the morning. I ran back to the classroom. On the floor, near my seat, the key was still there! I picked it up and felt happy again. On my way home, I told myself to be careful next time. That day, I learnt an important lesson: a small thing can bring a big worry.', '丢失的钥匙(一般过去时)', 108, 1, '[{"q": "Where did the writer finally find the key?", "answer": "B", "options": ["In the school bag.", "On the classroom floor near the seat.", "In a coat pocket.", "Under the bed."], "explanation": "''On the floor, near my seat, the key was still there''。"}, {"q": "How did the writer feel when the key was missing?", "answer": "A", "options": ["Worried.", "Happy.", "Bored.", "Angry."], "explanation": "''something worried me a lot ... My heart beat fast''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to open a door.", "Why school bags are big.", "Where the classroom is.", "How the writer lost and found a key."], "explanation": "全文讲丢钥匙又找回(过去时)。"}]'::jsonb, '[{"word": "key", "cn": "钥匙"}, {"word": "pocket", "cn": "口袋"}, {"word": "beat", "cn": "跳动(beat的过去式)"}, {"word": "careful", "cn": "细心的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'A rainy Sunday', 'Last Sunday, it rained all day, so we stayed at home. At first, I felt a little bored. I looked out of the window and watched the rain. Then my mother had a good idea. We made hot soup together in the kitchen. After lunch, I read a long story about a brave girl. My little brother drew pictures of animals. In the evening, the whole family played cards and laughed a lot. Outside, the rain was still falling, but inside it was warm and happy. A rainy day can be a good day too, if you spend it with the people you love.', '下雨的星期天(一般过去时)', 104, 1, '[{"q": "What did the writer and mother make together?", "answer": "C", "options": ["A card.", "A picture.", "Hot soup.", "A cake."], "explanation": "''We made hot soup together in the kitchen''。"}, {"q": "What did the little brother do?", "answer": "A", "options": ["Drew pictures of animals.", "Read a story.", "Played outside.", "Cooked lunch."], "explanation": "''My little brother drew pictures of animals''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to cook soup.", "How a family spent a happy rainy Sunday at home.", "Why it rains.", "Where the kitchen is."], "explanation": "全文讲雨天在家的温暖(过去时)。"}]'::jsonb, '[{"word": "bored", "cn": "无聊的"}, {"word": "soup", "cn": "汤"}, {"word": "drew", "cn": "画(draw的过去式)"}, {"word": "cards", "cn": "纸牌"}]'::jsonb);
-- U2 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'The last runner', 'It was the school sports day. In the 800-metre race, a thin boy named Danny ran at the back. Soon everyone else was far ahead. Could he still finish? It looked impossible. Halfway through, Danny''s legs hurt and he wanted to stop. Nobody would blame him if he gave up. But something inside him said, "Keep going." He did not stop. He was so slow that anyone could pass him, yet he never walked. The other runners finished, but Danny still ran, step by step, alone on the track. His face was red, but his eyes were full of hope. One small voice called his name, and soon the whole school joined in. Then something wonderful happened. Everyone in the playground began to cheer for him. "Come on, Danny!" No one laughed; everyone wanted him to finish. At last he crossed the line, tired but proud. He did not win anything, but he learned something important that day: the race is not always about being first. Sometimes finishing is enough.', '坚持·校运会最后一名', 171, 0, '[{"q": "Where did Danny run in the race?", "answer": "A", "options": ["At the back, behind everyone.", "At the very front.", "Beside the teacher.", "Off the track."], "explanation": "原文\"ran at the back\"、\"everyone else was far ahead\"。"}, {"q": "What did the people in the playground do near the end?", "answer": "B", "options": ["They laughed at Danny.", "They cheered for Danny.", "They went home.", "They stopped the race."], "explanation": "原文\"Everyone... began to cheer for him\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Danny was a fast runner.", "Sports day is boring.", "Never giving up is the real success.", "Running is bad for your legs."], "explanation": "结尾点题:坚持完成比第一更重要。"}, {"q": "Why did everyone start to cheer for Danny?", "answer": "D", "options": ["Because he was winning.", "Because he was funny.", "Because the race was over.", "Because they were moved by his refusal to give up."], "explanation": "他不放弃感动了大家;文中未直说,靠推断。"}, {"q": "\"He never gave up\" — \"gave up\" means ____.", "answer": "A", "options": ["stopped trying", "kept running", "fell down", "won the race"], "explanation": "由\"wanted to stop... did not stop\"可推断 give up=放弃、停止努力。"}]'::jsonb, '[{"word": "blame", "cn": "责怪"}, {"word": "track", "cn": "跑道"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'Is anyone there?', 'One evening, I was alone at home. Everyone in my family was out. Suddenly, I heard something in the kitchen. ''Is anyone there?'' I called, but nobody answered. My heart beat fast. I did not see anything strange, but the sound came again. I took a torch and looked around carefully. There was nothing behind the door and nothing under the table. Then I saw something small and grey. It was only our cat, playing with a bottle! I laughed at myself. Everything was fine after all. Sometimes we are afraid of nothing, and there is always someone or something simple behind a strange sound.', '有人在吗?(不定代词)', 105, 1, '[{"q": "What was really making the sound?", "answer": "C", "options": ["A stranger.", "The wind.", "The family cat.", "A bird."], "explanation": "''It was only our cat, playing with a bottle''。"}, {"q": "What did the writer take to look around?", "answer": "D", "options": ["A book.", "A bottle.", "A phone.", "A torch."], "explanation": "''I took a torch and looked around carefully''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer was afraid of a sound that turned out to be the cat.", "How to keep a cat.", "Why kitchens are dark.", "Where the family went."], "explanation": "全文讲被声音吓到,原是猫(不定代词)。"}]'::jsonb, '[{"word": "alone", "cn": "独自"}, {"word": "torch", "cn": "手电筒"}, {"word": "strange", "cn": "奇怪的"}, {"word": "bottle", "cn": "瓶子"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'Something in my bag', 'This morning, something in my school bag felt heavy. I opened it, but at first I could not find anything strange. Everything looked the same: my books, my pens and my lunch. Then I felt something hard at the bottom. It was a small box. Nobody told me about it. I opened the box carefully. Inside, there was a beautiful watch and a little note. The note said, ''Happy birthday from someone who loves you.'' It was from my mother! I forgot my own birthday, but my mother did not. Everyone in my family knew the secret except me. It was a lovely surprise, and I will keep the note for ever.', '书包里的东西(不定代词)', 112, 1, '[{"q": "What did the writer find at the bottom of the bag?", "answer": "B", "options": ["A book.", "A small box.", "A pen.", "A lunch."], "explanation": "''It was a small box ... Inside, there was a beautiful watch and a little note''。"}, {"q": "Who left the surprise in the bag?", "answer": "C", "options": ["A classmate.", "A teacher.", "The writer''s mother.", "A friend."], "explanation": "''It was from my mother!''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to pack a bag.", "Why bags are heavy.", "Where the watch was made.", "A sweet birthday surprise the writer found in the bag."], "explanation": "全文讲书包里的生日惊喜(不定代词)。"}]'::jsonb, '[{"word": "heavy", "cn": "重的"}, {"word": "box", "cn": "盒子"}, {"word": "note", "cn": "便条"}, {"word": "secret", "cn": "秘密"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'Nobody was late', 'Last Monday, our class had a special morning. Everyone came to school early, and nobody was late. We wanted to make everything ready for our teacher''s birthday. Someone brought flowers, and someone else brought a big card. Everybody wrote a few kind words on it. Nothing was too much trouble for us. We put balloons on the wall and cleaned every desk. When our teacher came in, she saw everything and could not say anything for a moment. Then she smiled, and there were happy tears in her eyes. That morning, everyone learnt something important: a little care from everybody can make someone very happy.', '没有人迟到(不定代词)', 106, 1, '[{"q": "Why did everyone come to school early?", "answer": "B", "options": ["To take a test.", "To make everything ready for the teacher''s birthday.", "To clean the street.", "To play games."], "explanation": "''We wanted to make everything ready for our teacher''s birthday''。"}, {"q": "What did the class put on the wall?", "answer": "A", "options": ["Balloons.", "Photos.", "Flowers.", "Cards."], "explanation": "''We put balloons on the wall''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to write a card.", "Why students are late.", "How a class made a surprise for their teacher''s birthday.", "Where the teacher lives."], "explanation": "全文讲全班为老师庆生(不定代词)。"}]'::jsonb, '[{"word": "special", "cn": "特别的"}, {"word": "balloons", "cn": "气球"}, {"word": "trouble", "cn": "麻烦"}, {"word": "tears", "cn": "眼泪"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'Looking for something to do', 'On the first day of the holiday, I had nothing to do. I walked around the house, but everything felt boring. ''Is there anything fun to do?'' I asked my father. ''Find something you love,'' he said. So I began to think. I did not want to watch television, and nobody was free to play with me. Then I remembered my old paint box. I took some paper and painted everything I could see: the tree, the sky and our cat. Soon, two hours went by. Nobody had to tell me to keep going. I learnt a simple truth: anyone can beat boredom by looking for something to love.', '找点事做(不定代词)', 109, 1, '[{"q": "What did the writer''s father tell him to do?", "answer": "A", "options": ["Find something he loves.", "Watch television.", "Clean the house.", "Sleep more."], "explanation": "''Find something you love, he said''。"}, {"q": "What did the writer paint?", "answer": "B", "options": ["Only the cat.", "The tree, the sky and the cat.", "Only the sky.", "A house."], "explanation": "''painted everything I could see: the tree, the sky and our cat''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to paint a cat.", "Why holidays are short.", "Where the paint box was.", "How the writer found something fun to do on a boring day."], "explanation": "全文讲无聊时找到爱做的事(不定代词)。"}]'::jsonb, '[{"word": "boring", "cn": "无聊的"}, {"word": "paint", "cn": "颜料;画"}, {"word": "paper", "cn": "纸"}, {"word": "boredom", "cn": "无聊"}]'::jsonb);
-- U3 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'Grandma''s noodles', 'Every winter, my grandma made hot noodles for the whole family. As soon as I opened the door, the kitchen smelled wonderful, and I felt warm at once. The noodles looked simple — just noodles, an egg and some green onions in a big bowl. But they tasted rich and warm. Grandma always said, "Good food does not need to be expensive." While we ate, the room grew warm and everyone became happy. My little brother''s face turned red from the hot soup, and we all laughed. Grandma watched us eat and her smile looked so kind. Sometimes she put a little sugar in my bowl, because I liked sweet things. On cold nights, one warm bowl could make my whole body feel happy. Now Grandma is old and cannot cook much, but that taste stays in my heart. When life feels hard, I think of her noodles. They were more than food; they were her love in a bowl. A meal made by someone who loves you always tastes sweet.', '食物·奶奶的面条', 180, 0, '[{"q": "What was in Grandma''s bowl of noodles?", "answer": "A", "options": ["Noodles, an egg and some green onions.", "Rice, beef and tofu.", "Bread and milk.", "Fish and potatoes."], "explanation": "原文\"just noodles, an egg and some green onions\"。"}, {"q": "Why did the little brother''s face turn red?", "answer": "B", "options": ["He was angry.", "From the hot soup.", "He ran too fast.", "He felt shy."], "explanation": "原文\"turned red from the hot soup\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Noodles are cheap.", "Grandma is a famous cook.", "Simple food made with love is precious.", "Winter is the best season."], "explanation": "结尾点题:充满爱的简单食物最珍贵。"}, {"q": "Why does that taste stay in the writer''s heart?", "answer": "D", "options": ["Because the noodles were expensive.", "Because the writer is always hungry.", "Because Grandma taught cooking classes.", "Because the noodles carry Grandma''s love."], "explanation": "\"they were her love in a bowl\",靠推断。"}, {"q": "\"The kitchen smelled wonderful\" — here \"smelled\" is a ____.", "answer": "A", "options": ["linking verb followed by an adjective", "past tense of \"smile\"", "kind of food", "noun"], "explanation": "smell 作系动词后接形容词,是感官系动词。"}]'::jsonb, '[{"word": "onion", "cn": "洋葱,葱"}, {"word": "restaurant", "cn": "餐馆"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'Grandma''s kitchen', 'I love my grandma''s kitchen very much. In the morning, it smells wonderful. The fresh bread smells sweet, and the hot soup smells rich. Everything looks warm and golden in the soft light. When I taste grandma''s noodles, they taste rich and fresh. The tea tastes sweet, and the cakes taste soft. Even the air feels gentle and kind. When grandma sings an old song, her voice sounds happy and calm. In her kitchen, I never feel sad or tired. Everything there feels like home. A good kitchen is not just about food; it makes a family feel close and warm.', '奶奶的厨房(系动词)', 110, 1, '[{"q": "How do grandma''s noodles taste?", "answer": "C", "options": ["Bad.", "Cold.", "Rich and fresh.", "Salty."], "explanation": "''they taste rich and fresh''。"}, {"q": "How does grandma''s voice sound when she sings?", "answer": "B", "options": ["Loud and hard.", "Happy and calm.", "Sad and tired.", "Weak and low."], "explanation": "''her voice sounds happy and calm''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Why the writer loves grandma''s warm kitchen.", "How to make noodles.", "Why restaurants are dear.", "Where grandma lives."], "explanation": "全文讲奶奶厨房的温暖(系动词)。"}]'::jsonb, '[{"word": "smells", "cn": "闻起来"}, {"word": "rich", "cn": "(味道)浓郁的"}, {"word": "gentle", "cn": "温柔的"}, {"word": "calm", "cn": "平静的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'The music sounds nice', 'Last night, I went to a school concert, and the music sounded wonderful. When the first song began, the room grew quiet. The soft piano sounded gentle, like rain on a window. Then the guitars grew loud and strong, and everyone felt excited. One singer had a voice that sounded sweet and clear. The music made me feel happy and calm at the same time. During a sad song, some people looked touched, and the hall felt very still. At the end, everybody clapped, and the players looked proud. Good music does something special: it makes a room full of strangers feel like friends.', '音乐听起来真美(系动词)', 104, 1, '[{"q": "What did the soft piano sound like?", "answer": "D", "options": ["Loud thunder.", "A busy street.", "A strong wind.", "Rain on a window."], "explanation": "''The soft piano sounded gentle, like rain on a window''。"}, {"q": "How did the players look at the end?", "answer": "A", "options": ["Proud.", "Tired.", "Sad.", "Bored."], "explanation": "''the players looked proud''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to play the piano.", "Why concerts are long.", "How wonderful the music felt at a school concert.", "Where the hall is."], "explanation": "全文讲音乐会音乐之美(系动词)。"}]'::jsonb, '[{"word": "concert", "cn": "音乐会"}, {"word": "piano", "cn": "钢琴"}, {"word": "touched", "cn": "感动的"}, {"word": "clapped", "cn": "鼓掌(clap的过去式)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'Autumn feels cool', 'Autumn is my favourite season, because everything feels fresh and cool. In the morning, the air feels crisp, and the wind smells clean. The leaves on the trees turn yellow, red and gold. They look like little fires in the sun. When I walk to school, the ground feels soft with fallen leaves. The fruit in the market tastes sweet, and hot tea tastes warm and good. The sky looks high and blue, and the clouds seem far away. In autumn, even a simple walk feels like a small holiday. The evenings grow dark early, and the birds fly south. I never feel bored, because the world around me looks new every single day.', '秋天的感觉(系动词)', 114, 1, '[{"q": "What colour do the leaves turn in autumn?", "answer": "D", "options": ["Green and blue.", "Grey and white.", "Black and brown.", "Yellow, red and gold."], "explanation": "''The leaves on the trees turn yellow, red and gold''。"}, {"q": "How does the fruit in the market taste?", "answer": "B", "options": ["Bad.", "Sweet.", "Salty.", "Bitter."], "explanation": "''The fruit in the market tastes sweet''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to grow fruit.", "Why leaves fall.", "Where the market is.", "Why the writer loves the feeling of autumn."], "explanation": "全文讲秋天的美好感觉(系动词)。"}]'::jsonb, '[{"word": "crisp", "cn": "清爽的"}, {"word": "leaves", "cn": "树叶"}, {"word": "fallen", "cn": "落下的"}, {"word": "clouds", "cn": "云"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'The soup tastes great', 'Today my father cooked dinner, and the soup tasted great. He tasted the soup twice before dinner. First, he cut some vegetables and an onion. Soon the kitchen smelled wonderful. ''This soup smells so good!'' I said. When it was ready, the soup looked golden and warm. I had a spoonful, and it tasted rich and warm. It was not too salty and not too sweet. ''It tastes just like grandma''s soup!'' my little sister said. My father looked very happy. The whole family felt warm and full after dinner. A simple meal, made with love, can taste wonderful. That evening, everything at our table felt just right.', '这汤味道好极了(系动词)', 102, 1, '[{"q": "What did the father cut for the soup?", "answer": "A", "options": ["Some vegetables and an onion.", "Fruit and rice.", "Eggs and bread.", "Meat and sugar."], "explanation": "''he cut some vegetables and an onion''。"}, {"q": "What did the little sister say the soup tasted like?", "answer": "C", "options": ["A restaurant meal.", "Something salty.", "Grandma''s soup.", "Nothing at all."], "explanation": "''It tastes just like grandma''s soup!''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to cut an onion.", "A simple, tasty soup that made the family happy.", "Why restaurants are dear.", "Where the kitchen is."], "explanation": "全文讲爸爸做的美味汤(系动词)。"}]'::jsonb, '[{"word": "onion", "cn": "洋葱"}, {"word": "spoon", "cn": "勺子"}, {"word": "salty", "cn": "咸的"}, {"word": "golden", "cn": "金黄色的"}]'::jsonb);
-- U4 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'Study, but play too', 'Last term, my friend Ben studied all the time. Every day after school, he did his homework until late at night. He never played sports and seldom saw his friends. "I must work hard," he always said. But soon Ben looked tired and unhappy, and his marks did not go up. One day our teacher gave him some good advice. "Ben," she said, "work hard, but don''t forget to rest. Play some sport. Meet your friends. A tired mind cannot learn well." Ben decided to try. He began to play basketball twice a week. On weekends, he went out with his friends. At first he worried about losing study time, but something surprising happened. He felt happy, and his mind became clear and quick. His marks even went up. He slept well at night and woke up happy. He also made new friends when he played, and school did not feel boring any more. Now Ben knows the secret: don''t just study all day. Take a break, have some fun, and then go back to your books. Work and play are like two legs — you need both to walk well.', '劳逸结合', 189, 0, '[{"q": "What did Ben do every day after school at first?", "answer": "A", "options": ["Homework until late at night.", "Played basketball.", "Went out with friends.", "Watched TV."], "explanation": "原文\"did his homework until late at night\"。"}, {"q": "How often did Ben play basketball after taking the advice?", "answer": "B", "options": ["Every day.", "Twice a week.", "Once a month.", "Never."], "explanation": "原文\"play basketball twice a week\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Homework is not important.", "Basketball is the best sport.", "Balancing work and play helps you do well.", "Teachers give too much advice."], "explanation": "结尾点题:劳逸结合,学得好也玩得好。"}, {"q": "Why did Ben''s marks go up after he started to play?", "answer": "D", "options": ["Because he stopped studying.", "Because the tests were not hard.", "Because his teacher helped him cheat.", "Because rest made his mind clear and he learned well."], "explanation": "\"his mind became clear and quick\"→学得好;靠推断。"}, {"q": "\"Take a break\" means ____.", "answer": "A", "options": ["stop working for a short rest", "break something", "run away", "study all night"], "explanation": "由上下文\"have some fun, and then go back\"可推断 take a break=短暂休息。"}]'::jsonb, '[{"word": "advice", "cn": "建议"}, {"word": "mark", "cn": "分数,成绩"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'How to stay healthy', 'Do you want to stay healthy and strong? Here are a few simple rules. First, eat more fruit and vegetables, and drink plenty of water. Don''t eat too much sweet food. Second, go to bed early and get up early. Don''t stay up late playing games. Third, do some exercise every day. Run, swim or play ball with your friends. Remember to wash your hands before meals. Don''t forget to brush your teeth in the morning and at night. Last of all, keep a happy heart, and smile more often. Follow these rules, and you will feel fresh and full of energy every day. Good health starts with small habits.', '怎样保持健康(祈使句)', 113, 1, '[{"q": "What should you drink plenty of?", "answer": "C", "options": ["Sweet drinks.", "Milk only.", "Water.", "Hot tea."], "explanation": "''drink plenty of water''。"}, {"q": "When should you brush your teeth?", "answer": "D", "options": ["Only in the morning.", "Only at night.", "After every meal.", "In the morning and at night."], "explanation": "''brush your teeth in the morning and at night''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Simple rules that help you stay healthy.", "How to play ball.", "Why fruit is sweet.", "Where to buy water."], "explanation": "全文讲保持健康的建议(祈使句)。"}]'::jsonb, '[{"word": "plenty", "cn": "充足"}, {"word": "exercise", "cn": "锻炼"}, {"word": "teeth", "cn": "牙齿"}, {"word": "energy", "cn": "精力"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'How to be a good friend', 'A good friend is a treasure, so learn to be one. Be kind, and always speak in a gentle way. Listen carefully when your friend talks, and don''t laugh at their mistakes. When your friend is sad, stay close and help. Share your things, and share your time too. Don''t tell your friend''s secrets to anyone. If you quarrel, say sorry first; don''t let a small thing break a good friendship. Remember birthdays, and give a warm smile every day. Be honest, but be kind with the truth. Never laugh at a friend in trouble. Please keep every promise you make. Follow these simple rules, and you will keep your friends for many years. A true friend is like gold.', '怎样做好朋友(祈使句)', 111, 1, '[{"q": "What should you do when your friend is sad?", "answer": "B", "options": ["Laugh at them.", "Stay close and help.", "Leave them alone.", "Tell others."], "explanation": "''When your friend is sad, stay close and help''。"}, {"q": "What should you do first if you quarrel?", "answer": "A", "options": ["Say sorry first.", "Walk away.", "Shout at him.", "Tell a secret."], "explanation": "''If you quarrel, say sorry first''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to find gold.", "Why friends quarrel.", "Simple rules for being a good friend.", "Where friends meet."], "explanation": "全文讲怎样做好朋友(祈使句)。"}]'::jsonb, '[{"word": "treasure", "cn": "珍宝"}, {"word": "gentle", "cn": "温和的"}, {"word": "secrets", "cn": "秘密"}, {"word": "honest", "cn": "诚实的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'How to plant a flower', 'Would you like to grow a beautiful flower? It is easy if you follow these steps. First, find a clean pot and fill it with soft soil. Next, make a small hole in the middle with your finger. Put one seed in the hole, and cover it gently with soil. Then give it a little water, but don''t give it too much. Put the pot near a window, so it can get plenty of sun. Water the seed every day, and wait with patience. Don''t pull the plant to make it grow quickly. In a few weeks, a green leaf will come out. Care for it well, and soon your flower will bloom.', '怎样种一朵花(祈使句)', 115, 1, '[{"q": "What should you fill the pot with first?", "answer": "D", "options": ["Water.", "Stones.", "Sand.", "Soft soil."], "explanation": "''fill it with soft soil''。"}, {"q": "Why should you put the pot near a window?", "answer": "B", "options": ["To keep it warm at night.", "So it can get plenty of sun.", "To hide it.", "To water it easily."], "explanation": "''Put the pot near a window, so it can get plenty of sun''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The steps to plant and grow a flower.", "How to buy a pot.", "Why flowers are red.", "Where seeds come from."], "explanation": "全文讲种花的步骤(祈使句)。"}]'::jsonb, '[{"word": "pot", "cn": "花盆"}, {"word": "soil", "cn": "土壤"}, {"word": "seed", "cn": "种子"}, {"word": "bloom", "cn": "开花"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'Keep our classroom clean', 'Our classroom is our second home, so let''s keep it clean and tidy. Put your books neatly on the desk, and don''t leave rubbish on the floor. When you finish a snack, throw the paper into the bin. Don''t draw on the walls or the desks. Every day, some students should sweep the floor and clean the windows. Water the plants near the window, and don''t let them dry out. Open the windows in the morning to let in fresh air. Before you go home, push in your chair and turn off the lights. If everyone helps a little, our classroom will always look bright and feel pleasant. A clean room makes a happy class.', '保持教室整洁(祈使句)', 119, 1, '[{"q": "What should you do with the paper after a snack?", "answer": "C", "options": ["Leave it on the desk.", "Put it in your bag.", "Throw it into the bin.", "Give it to the teacher."], "explanation": "''throw the paper into the bin''。"}, {"q": "What should you do before you go home?", "answer": "D", "options": ["Open the windows.", "Water the plants.", "Draw on the walls.", "Push in your chair and turn off the lights."], "explanation": "''push in your chair and turn off the lights''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to water plants.", "How to keep the classroom clean and tidy.", "Why classrooms are small.", "Where the bin is."], "explanation": "全文讲保持教室整洁(祈使句)。"}]'::jsonb, '[{"word": "tidy", "cn": "整洁的"}, {"word": "rubbish", "cn": "垃圾"}, {"word": "bin", "cn": "垃圾桶"}, {"word": "sweep", "cn": "扫"}]'::jsonb);
-- U5 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'The colours of my village', 'My village is a small place among green hills, and it is the most beautiful place I know. In spring, the hills turn greener than in any other season, and wild flowers open everywhere. The air smells fresh, and the small river runs clearer than glass. Summer is the busiest time. The trees grow taller and thicker, and the fields become a sea of green. It is hotter than spring, but the tall trees give us cool shade. Autumn is my favourite. The leaves turn from green to gold, and the hills look like a big painting. The apples on the trees are the sweetest of the year, and the sky seems higher and bluer. People come to pick the sweet apples, and the whole hill smells fresh and clean. Winter is the quietest season. White snow covers the hills, and the world looks cleaner and brighter than ever. Children run out to play in the snow, and their happy voices fill the cold air. Some people think big cities are more exciting than a small village. But to me, my home among the hills is truly lovely. Each season paints my village a different colour, and I love them all.', '家乡的自然色彩', 201, 0, '[{"q": "When do the hills turn greenest?", "answer": "A", "options": ["In spring.", "In summer.", "In autumn.", "In winter."], "explanation": "原文\"In spring, the hills turn greener than in any other season\"。"}, {"q": "What is the writer''s favourite season?", "answer": "B", "options": ["Spring.", "Autumn.", "Summer.", "Winter."], "explanation": "原文\"Autumn is my favourite\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Cities are better than villages.", "Winter is too cold.", "The writer loves the changing beauty of the home village.", "Apples grow best in autumn."], "explanation": "全文写家乡四季之美,结尾点题热爱家乡。"}, {"q": "Why does the writer prefer the village to a big city?", "answer": "D", "options": ["Because the village has more shops.", "Because cities are dangerous.", "Because the village is bigger.", "Because to the writer home is truly lovely."], "explanation": "\"my home among the hills is truly lovely\",靠推断。"}, {"q": "\"The river runs clearer than glass\" shows the water is very ____.", "answer": "A", "options": ["clean and clear", "dirty", "deep", "cold"], "explanation": "clearer than glass=像玻璃一样清澈,说明水很干净。"}]'::jsonb, '[{"word": "shade", "cn": "树荫"}, {"word": "field", "cn": "田野"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'The seasons of my hometown', 'My hometown is beautiful all year, but each season has its own colour. Spring is the greenest season. The hills grow greener day by day, and the flowers make the fields brighter than a painting. Summer is the warmest time. The trees are taller and thicker, and the river runs faster after the rain. Autumn is the most colourful season of all. The leaves turn redder and more golden every week. But winter is the quietest and the most peaceful time. The snow makes the whole town cleaner and whiter than ever. Of all the seasons, I love autumn best, because it is the most beautiful season in my hometown.', '家乡的四季(比较级最高级)', 110, 1, '[{"q": "Which season is the warmest?", "answer": "C", "options": ["Spring.", "Autumn.", "Summer.", "Winter."], "explanation": "''Summer is the warmest time''。"}, {"q": "Which season does the writer love best?", "answer": "A", "options": ["Autumn.", "Spring.", "Summer.", "Winter."], "explanation": "''I love autumn best ... the most beautiful season''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to paint a picture.", "Why snow is white.", "Where the river is.", "How each season colours the writer''s hometown."], "explanation": "全文讲家乡四季之美(比较级最高级)。"}]'::jsonb, '[{"word": "hometown", "cn": "家乡"}, {"word": "greenest", "cn": "最绿的"}, {"word": "colourful", "cn": "多彩的"}, {"word": "peaceful", "cn": "宁静的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'My family', 'There are five people in my family, and we are all different. My father is the tallest of us all. He is also the strongest, and he can carry me on his back with ease. My mother is shorter than my father, but she is the kindest person I know. My big brother is older than me. He is cleverer at maths, but I run faster than him. My little sister is the youngest and the funniest. She makes the whole family laugh. I am not the tallest or the cleverest, but I am the busiest, because I have the most homework! We are all different, yet we love each other the most in the world.', '我的家人(比较级最高级)', 116, 1, '[{"q": "Who is the tallest in the family?", "answer": "B", "options": ["The brother.", "The father.", "The mother.", "The writer."], "explanation": "''My father is the tallest of us all''。"}, {"q": "Who is the youngest and the funniest?", "answer": "A", "options": ["The little sister.", "The mother.", "The brother.", "The father."], "explanation": "''My little sister is the youngest and the funniest''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to do maths.", "Why fathers are strong.", "How the members of the writer''s family are different.", "Where the family lives."], "explanation": "全文讲家人各有不同(比较级最高级)。"}]'::jsonb, '[{"word": "tallest", "cn": "最高的"}, {"word": "strongest", "cn": "最强壮的"}, {"word": "cleverer", "cn": "更聪明的"}, {"word": "youngest", "cn": "最小的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'City and countryside', 'My family once lived in a big city, but now we live in the countryside. The two places are very different. The city is busier and noisier. The streets are more crowded, and the buildings are much taller. Life there is faster, and the shops are bigger. But the countryside is quieter and cleaner. The air is fresher, and the sky looks bluer at night, and the stars are the brightest in the world. In the city, I had more shops to visit, but here I have more space to run and play. Both places have good things. For me, the countryside is the more peaceful home, and I sleep better here than ever before.', '城市与乡村(比较级最高级)', 115, 1, '[{"q": "How is the air in the countryside?", "answer": "B", "options": ["Dirtier.", "Fresher.", "Warmer.", "Heavier."], "explanation": "''The air is fresher''。"}, {"q": "What did the writer have more of in the city?", "answer": "D", "options": ["Space to run.", "Bright stars.", "Fresh air.", "Shops to visit."], "explanation": "''In the city, I had more shops to visit''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to move house.", "Why stars shine.", "How the city and the countryside are different.", "Where the shops are."], "explanation": "全文讲城市与乡村的不同(比较级最高级)。"}]'::jsonb, '[{"word": "countryside", "cn": "乡村"}, {"word": "crowded", "cn": "拥挤的"}, {"word": "fresher", "cn": "更清新的"}, {"word": "space", "cn": "空间"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'The best place to read', 'I love reading, and I once looked for the best place to do it. My bedroom is quiet, but it is sometimes too warm. The kitchen is brighter, but it is also the noisiest room in the house. The park is nice, yet it is often more crowded than I like. Then I found the perfect place: a small corner in the library. It is the quietest place of all. The light is softer there, and the chairs are more comfortable than at home. Best of all, there are more books around me than I could ever read. Now the library corner is my favourite place, and I read better and longer there than anywhere else.', '最好的读书地方(比较级最高级)', 116, 1, '[{"q": "Why is the kitchen not a good place to read?", "answer": "D", "options": ["It is too dark.", "It is too cold.", "It has no chairs.", "It is the noisiest room."], "explanation": "''the kitchen ... is also the noisiest room in the house''。"}, {"q": "What is the best thing about the library corner?", "answer": "B", "options": ["It is warm.", "There are more books than the writer could ever read.", "It is crowded.", "It is near home."], "explanation": "''there are more books around me than I could ever read''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer found the best place to read.", "How to build a library.", "Why bedrooms are warm.", "Where the park is."], "explanation": "全文讲寻找最佳读书地(比较级最高级)。"}]'::jsonb, '[{"word": "comfortable", "cn": "舒适的"}, {"word": "corner", "cn": "角落"}, {"word": "library", "cn": "图书馆"}, {"word": "noisiest", "cn": "最吵的"}]'::jsonb);
-- U6 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'A trip to the mountains and the sea', 'Last summer, my family took a long trip. In the first week, we went to the mountains in the west. The air up there was as cool as autumn, even in July. Climbing was not as easy as I thought, and by evening my legs were as heavy as stone. But the view from the top was as beautiful as a painting, and I forgot all my tired feelings. In the second week, we drove to the sea in the east. The beach was as bright as gold under the sun, and the water felt as warm as a bath. My little sister was as happy as a bird; she played in the sand all day. We made a small house of sand together, and the sea slowly took it away, but we only laughed. The sea was not as quiet as the mountains, but it was just as lovely. At night, the stars over the sea looked as many as the lights of a big city. The mountains and the sea were very different, yet each was as wonderful as the other. That trip taught me something: the world is as wide as your dreams, so go and see it.', '旅行·山与海', 200, 0, '[{"q": "How did the air in the mountains feel in July?", "answer": "A", "options": ["As cool as autumn.", "As hot as a fire.", "As wet as rain.", "As cold as winter."], "explanation": "原文\"as cool as autumn, even in July\"。"}, {"q": "What did the little sister do at the beach?", "answer": "B", "options": ["Climbed the mountains.", "Played in the sand all day.", "Read a book.", "Slept in the car."], "explanation": "原文\"played in the sand all day\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Mountains are better than the sea.", "Summer is too hot for trips.", "Both the mountains and the sea were wonderful in their own ways.", "Travelling is always tiring."], "explanation": "结尾点题:山与海各美其美。"}, {"q": "Why did the writer forget the tired feelings at the top?", "answer": "D", "options": ["Because the trip ended.", "Because the sister helped.", "Because it got cold.", "Because the beautiful view made the writer happy."], "explanation": "\"the view... was as beautiful as a painting, and I forgot all my tired feelings\",靠推断。"}, {"q": "\"The world is as wide as your dreams\" encourages readers to ____.", "answer": "A", "options": ["explore widely and dream big", "stay at home", "stop dreaming", "travel less"], "explanation": "由\"go and see it\"可推断:鼓励去广阔世界、勇敢追梦。"}]'::jsonb, '[{"word": "view", "cn": "景色,风景"}, {"word": "climb", "cn": "攀登"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'My two best friends', 'I have two best friends, Anna and Kate, and I love them the same. In some ways, they are as alike as two peas, but in other ways they are very different. Anna is as tall as Kate, and they are both as old as me. Anna is as kind as an angel; she is always ready to help. Kate is not as quiet as Anna, but she is just as clever. On the sports field, Anna runs as fast as the wind, while Kate cannot run as fast, yet she plays basketball just as well. When I am sad, they are both as warm as sunshine. A good friend does not need to be as perfect as a hero, only as true as these two.', '我的两个朋友(as...as)', 126, 1, '[{"q": "Who runs as fast as the wind?", "answer": "B", "options": ["Kate.", "Anna.", "The writer.", "No one."], "explanation": "''Anna runs as fast as the wind''。"}, {"q": "What does Kate play just as well?", "answer": "D", "options": ["Football.", "Running.", "Music.", "Basketball."], "explanation": "''she plays basketball just as well''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The writer''s two friends and how they are alike and different.", "How to run fast.", "Why basketball is hard.", "Where the sports field is."], "explanation": "全文讲两个好友的异同(as..as)。"}]'::jsonb, '[{"word": "alike", "cn": "相似的"}, {"word": "angel", "cn": "天使"}, {"word": "sunshine", "cn": "阳光"}, {"word": "true", "cn": "忠诚的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'Mountains and the sea', 'Last summer, my family visited both the mountains and the sea, and I loved them the same. The mountains were as beautiful as a painting. The air up there was as fresh as a spring morning. Climbing was hard, but the view from the top was as wide as the whole sky. Later, we went to the sea. The water was as blue as the sky above it. The waves were not so quiet as the mountains, but they were just as lovely. I swam in water as warm as a bath. The sea was as full of life as the green hills. In the end, I could not say which place I loved more. Both were as wonderful as a dream.', '山与海(as...as)', 122, 1, '[{"q": "How was the air in the mountains?", "answer": "C", "options": ["As cold as winter.", "As dry as sand.", "As fresh as a spring morning.", "As warm as a bath."], "explanation": "''The air up there was as fresh as a spring morning''。"}, {"q": "What was the sea water as blue as?", "answer": "B", "options": ["The green hills.", "The sky above it.", "A painting.", "A dream."], "explanation": "''The water was as blue as the sky above it''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to swim in the sea.", "Why mountains are high.", "Where the family lives.", "How the writer loved both the mountains and the sea."], "explanation": "全文讲山海皆美(as..as)。"}]'::jsonb, '[{"word": "view", "cn": "景色"}, {"word": "waves", "cn": "海浪"}, {"word": "lovely", "cn": "可爱的"}, {"word": "dream", "cn": "梦"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'The twins', 'My neighbours have twin boys, Tom and Sam. They look almost the same, but they are not as alike as people think. Tom is as tall as Sam, and they are exactly as old as each other. In class, Tom is as clever as Sam, and both study just as hard. But on the sports field, Tom cannot run as fast as Sam. Sam, on the other hand, does not draw as well as Tom. When they play music, Tom sings as sweetly as a bird, while Sam plays the guitar just as beautifully. They are as close as two brothers can be. No two people are ever exactly as alike as twins, and yet even twins are never the same.', '双胞胎兄弟(as...as)', 121, 1, '[{"q": "Who can run faster, Tom or Sam?", "answer": "A", "options": ["Sam.", "Tom.", "They run the same.", "Neither runs."], "explanation": "''Tom cannot run as fast as Sam''。"}, {"q": "What does Tom do as sweetly as a bird?", "answer": "C", "options": ["Draw.", "Play guitar.", "Sing.", "Run."], "explanation": "''Tom sings as sweetly as a bird''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to sing well.", "Why twins are tall.", "Where the twins live.", "How twin brothers are alike yet different."], "explanation": "全文讲双胞胎的异同(as..as)。"}]'::jsonb, '[{"word": "twins", "cn": "双胞胎"}, {"word": "exactly", "cn": "恰好"}, {"word": "neighbours", "cn": "邻居"}, {"word": "beautifully", "cn": "优美地"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'A day as busy as ever', 'Yesterday was as busy as any school day, but it was also a very happy one. In the morning, I got up as early as the sun. The classes were as full as always, but they were as interesting as a good story. At lunch, the canteen was as noisy as a market, yet the food was as tasty as home cooking. In the afternoon, our football match was as exciting as a real game. My team did not play as well as last week, but we tried just as hard. By evening, I was as tired as a runner after a race. Still, I slept as sweetly as a baby. A busy day can be as good as a holiday, if you fill it with things you love.', '和往常一样忙的一天(as...as)', 129, 1, '[{"q": "How early did the writer get up?", "answer": "C", "options": ["As late as noon.", "After the classes.", "As early as the sun.", "Before midnight."], "explanation": "''I got up as early as the sun''。"}, {"q": "How did the writer sleep by evening?", "answer": "B", "options": ["Badly.", "As sweetly as a baby.", "Not at all.", "As little as before."], "explanation": "''I slept as sweetly as a baby''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How a busy school day can also be a happy one.", "How to play football.", "Why canteens are noisy.", "Where the match was."], "explanation": "全文讲忙碌又快乐的一天(as..as)。"}]'::jsonb, '[{"word": "canteen", "cn": "食堂"}, {"word": "match", "cn": "比赛"}, {"word": "exciting", "cn": "激动人心的"}, {"word": "runner", "cn": "跑步者"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; intn int; extn int; qbad int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B';
  IF tot<>30 THEN RAISE EXCEPTION 'total=% 期望30', tot; END IF;
  SELECT count(*) INTO intn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' AND difficulty=0;
  IF intn<>6 THEN RAISE EXCEPTION '精读(diff0)=% 期望6', intn; END IF;
  SELECT count(*) INTO extn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' AND difficulty=1;
  IF extn<>24 THEN RAISE EXCEPTION '泛读(diff1)=% 期望24', extn; END IF;
  SELECT count(*) INTO qbad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B'
    AND NOT ((difficulty=0 AND jsonb_array_length(questions)=5) OR (difficulty=1 AND jsonb_array_length(questions)=3));
  IF qbad<>0 THEN RAISE EXCEPTION '题数不符(精读5/泛读3)的篇=%', qbad; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY unit HAVING count(*)<>5) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠5篇(1精读+4泛读)的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy7B 阅读 % 篇(精读6+泛读24)· 6单元各5', tot;
END $$;

COMMIT;

SELECT unit, difficulty, count(*) 篇, min(jsonb_array_length(questions))||'-'||max(jsonb_array_length(questions)) 题数 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY unit,difficulty ORDER BY unit,difficulty DESC;